const techniques = [
  ['T1566','Phishing','covered'],['T1059','Command shell','covered'],['T1078','Valid accounts','gap'],['T1105','Ingress tool','covered'],['T1021','Remote services','empty'],['T1003','Credential dump','covered'],['T1071','Web protocols','gap'],['T1041','Exfiltration','covered'],['T1486','Data encrypted','covered'],['T1547','Boot startup','empty'],['T1053','Scheduled task','covered'],['T1562','Impair defenses','empty'],['T1090','Proxy','covered'],['T1112','Modify registry','empty']
];
const variants = [
  {name:'Silent Beacon / v04',persona:'Ransomware affiliate',desc:'Fast, noisy, profit-motivated',initials:'RF',objective:'C2 beacon blend-in',path:'T1071.001 · Web protocols',cell:6,rule:['where process.name == "curl"','and destination.port == 443'],evades:true,events:[['13:45:02','auth','svc-backup · login success','normal'],['13:45:04','process','backup-agent.exe started','normal'],['13:45:07','network','win-update-cache.net:443 · 34 KB','test']]},
  {name:'Paper Trail / v08',persona:'Insider',desc:'Low volume, access-aware',initials:'IN',objective:'Archive staging',path:'T1074.001 · Local data staging',cell:2,rule:['where file.extension == "zip"','and user.role == "contractor"'],evades:false,events:[['13:46:12','auth','a.nguyen · VPN session renewed','normal'],['13:46:20','file','quarterly-plan.zip created','test'],['13:46:22','network','fileshare-east · 18 MB','normal']]},
  {name:'Winter Static / v11',persona:'State actor',desc:'Slow, quiet, patient',initials:'SA',objective:'Remote service discovery',path:'T1046 · Network service discovery',cell:4,rule:['where event.category == "network"','and destination.port in (22, 3389, 445)'],evades:true,events:[['13:47:01','process','inventory-sync.exe started','normal'],['13:47:19','network','10.24.8.12:445 · 1.2 KB','test'],['13:47:33','network','10.24.8.14:445 · 1.1 KB','test']]}
];
let variantIndex = 0, covered = 8;
const matrix = document.querySelector('#matrix');
const score = document.querySelector('#score');
const note = document.querySelector('#matrixNote');
const button = document.querySelector('#runButton');
function renderMatrix(testing=-1){ matrix.innerHTML = techniques.map((t,i)=>`<div class="cell ${i===testing?'testing':t[2]}" data-cell="${i}"><span>${t[0]}</span><b>${t[1]}</b></div>`).join(''); }
function eventsFor(items){ const background=[['13:44:58','network','cdn.assets.internal:443 · 8 KB','normal'],['13:45:00','process','chrome.exe started','normal']]; const all=[...background,...items]; document.querySelector('#eventList').innerHTML=all.map(e=>`<div class="event"><span class="time">${e[0]}</span><span class="type">${e[1]}</span><span class="detail">${e[2]}</span><span class="tag ${e[3]==='test'?'alert':''}">${e[3]==='test'?'synthetic':'baseline'}</span></div>`).join(''); }
function setText(id,value){document.querySelector(id).textContent=value}
function loadVariant(v){setText('#exerciseName',v.name);setText('#personaName',v.persona);setText('#personaDesc',v.desc);document.querySelector('.persona-badge').textContent=v.initials;setText('#objective',v.objective);setText('#attackPath',v.path);setText('#variant',String(variantIndex+4).padStart(2,'0')+' / 12');setText('#ruleQuery',v.rule[0]);setText('#ruleQuery2',v.rule[1]);eventsFor(v.events);document.querySelectorAll('.workflow-step').forEach(x=>x.className='workflow-step');const result=document.querySelector('#ruleResult');result.className='result initial';result.textContent='READY';renderMatrix();}
function sleep(ms){return new Promise(r=>setTimeout(r,ms))}
async function run(){const v=variants[variantIndex];button.disabled=true;button.innerHTML='Running telemetry…';setText('#redState','injecting variant');setText('#blueState','evaluating');renderMatrix(v.cell);document.querySelectorAll('.workflow-step')[0].classList.add('active');await sleep(1050);const result=document.querySelector('#ruleResult');if(v.evades){result.className='result evaded';result.textContent='EVADED';document.querySelectorAll('.workflow-step')[0].className='workflow-step done';setText('#redState','gap confirmed');setText('#blueState','authoring rule');setText('#streamStatus','Variant passed existing rules');show(`Gap found: ${v.path}. Blue agent opened a detection PR.`);await sleep(1050);document.querySelectorAll('.workflow-step')[1].className='workflow-step done';setText('#blueState','PR #184 ready');setText('#branch','pr/184-'+v.path.slice(0,5).toLowerCase());await sleep(900);document.querySelectorAll('.workflow-step')[2].className='workflow-step active';setText('#blueState','re-testing merged rule');await sleep(900);document.querySelectorAll('.workflow-step')[2].className='workflow-step done';techniques[v.cell][2]='covered';covered++;score.textContent=Math.round(covered/14*100)+'%';note.textContent=`${covered} of 14 technique paths covered`;result.className='result caught';result.textContent='CAUGHT';renderMatrix();setText('#streamStatus','Re-test caught by PR #184');show('PR #184 merged → retest passed. Coverage increased.');}else{result.className='result caught';result.textContent='CAUGHT';document.querySelectorAll('.workflow-step')[0].className='workflow-step done';setText('#redState','variant contained');setText('#blueState','rule holds');setText('#streamStatus','Existing rule caught synthetic event');show('Existing rule contained this variant. No rule change needed.');renderMatrix();}setText('#redState','mutating telemetry');button.disabled=false;button.innerHTML='<span class="play">▶</span> Run next variant';variantIndex=(variantIndex+1)%variants.length;setTimeout(()=>loadVariant(variants[variantIndex]),900)}
let toastTimer;function show(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3300)}
renderMatrix();loadVariant(variants[0]);button.addEventListener('click',run);
